    public static void apply(ModelGhidorah model, Channel[] channels, float timeSec) {
        if (channels == null) return;
        for (Channel c : channels) {
            ModelPart part = model.getBone(c.bone);
            if (part == null) continue;
            float dur = c.times.length == 0 ? 1f : c.times[c.times.length - 1];
            if (dur <= 1e-4f) dur = 1f;
            float t = timeSec % dur;
            if (t < 0) t += dur;
            int i = 0;
            while (i + 1 < c.times.length && c.times[i + 1] < t) i++;
            int j = Math.min(i + 1, c.times.length - 1);
            float t0 = c.times[i];
            float t1 = c.times[j];
            float a = t1 > t0 ? (t - t0) / (t1 - t0) : 0f;
            a = Mth.clamp(a, 0f, 1f);
            if (c.path == 0) {
                float x0 = c.values[i * 4], y0 = c.values[i * 4 + 1], z0 = c.values[i * 4 + 2], w0 = c.values[i * 4 + 3];
                float x1 = c.values[j * 4], y1 = c.values[j * 4 + 1], z1 = c.values[j * 4 + 2], w1 = c.values[j * 4 + 3];
                float dot = x0 * x1 + y0 * y1 + z0 * z1 + w0 * w1;
                if (dot < 0) { x1 = -x1; y1 = -y1; z1 = -z1; w1 = -w1; }
                float x = x0 + (x1 - x0) * a;
                float y = y0 + (y1 - y0) * a;
                float z = z0 + (z1 - z0) * a;
                float w = w0 + (w1 - w0) * a;
                float inv = 1f / (float) Math.sqrt(x * x + y * y + z * z + w * w);
                x *= inv; y *= inv; z *= inv; w *= inv;
                float[] e = quatToEuler(x, y, z, w);
                part.xRot = e[0];
                part.yRot = e[1];
                part.zRot = e[2];
            } else if (c.path == 1) {
                part.x = c.values[i * 3] + (c.values[j * 3] - c.values[i * 3]) * a;
                part.y = c.values[i * 3 + 1] + (c.values[j * 3 + 1] - c.values[i * 3 + 1]) * a;
                part.z = c.values[i * 3 + 2] + (c.values[j * 3 + 2] - c.values[i * 3 + 2]) * a;
            }
        }
    }

    private static float[] quatToEuler(float qx, float qy, float qz, float qw) {
        float sinr = 2 * (qw * qx + qy * qz);
        float cosr = 1 - 2 * (qx * qx + qy * qy);
        float xRot = (float) Math.atan2(sinr, cosr);
        float sinp = 2 * (qw * qy - qz * qx);
        float yRot = Math.abs(sinp) >= 1 ? (float) Math.copySign(Math.PI / 2, sinp) : (float) Math.asin(sinp);
        float siny = 2 * (qw * qz + qx * qy);
        float cosy = 1 - 2 * (qy * qy + qz * qz);
        float zRot = (float) Math.atan2(siny, cosy);
        return new float[] { xRot, yRot, zRot };
    }
